MOD=998244353

def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n,m=data[:2]
    a=[x-1 for x in data[2:]]
    children=[[] for _ in range(n)]
    indeg=[0]*n
    for u,p in enumerate(a):
        children[p].append(u); indeg[p]+=1
    q=[u for u in range(n) if indeg[u]==0]
    order=[]
    for u in q:
        order.append(u)
        p=a[u]; indeg[p]-=1
        if indeg[p]==0:q.append(p)
    cyc=[indeg[u]>0 for u in range(n)]
    dp=[None]*n
    for u in order:
        cur=[1]*m
        for v in children[u]:
            pref=0; ar=dp[v]
            for j in range(m):
                pref=(pref+ar[j])%MOD
                cur[j]=cur[j]*pref%MOD
        dp[u]=cur
    seen=[False]*n
    ans=1
    for s in range(n):
        if not cyc[s] or seen[s]:continue
        nodes=[]; v=s
        while not seen[v]:
            seen[v]=True; nodes.append(v); v=a[v]
        factors=[1]*m
        for u in nodes:
            for ch in children[u]:
                if not cyc[ch]:
                    pref=0; ar=dp[ch]
                    for j in range(m):
                        pref=(pref+ar[j])%MOD
                        factors[j]=factors[j]*pref%MOD
        ans=ans*(sum(factors)%MOD)%MOD
    print(ans)
if __name__=='__main__':solve()

