import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    mx = max(a)

    spf = list(range(mx + 1))
    for p in range(2, int(mx ** 0.5) + 1):
        if spf[p] == p:
            for q in range(p * p, mx + 1, p):
                if spf[q] == q:
                    spf[q] = p

    phi = list(range(mx + 1))
    for p in range(2, mx + 1):
        if phi[p] == p:
            for q in range(p, mx + 1, p):
                phi[q] -= phi[q] // p

    freq = [0] * (mx + 1)
    divisor_cache = {}
    ans = 0
    weight = 1
    out = []

    for x in a:
        divs = divisor_cache.get(x)
        if divs is None:
            z = x
            factors = []
            while z > 1:
                p = spf[z]
                e = 0
                while z % p == 0:
                    z //= p
                    e += 1
                factors.append((p, e))
            divs = [1]
            for p, e in factors:
                old = divs[:]
                multiple = 1
                for _ in range(e):
                    multiple *= p
                    divs.extend(d * multiple for d in old)
            divisor_cache[x] = divs

        total = 0
        for d in divs:
            total += phi[d] * freq[d]
            v = freq[d] + weight
            if v >= MOD:
                v -= MOD
            freq[d] = v

        ans = (2 * ans + total) % MOD
        out.append(str(ans))
        weight = (weight * 2) % MOD

    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

