from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, idx))
        first_val = second_val = 0
        first_id = -1
        gain = [0] * m
        total = 0
        for r in range(1, n + 1):
            for a, idx in buckets[r]:
                if a > first_val:
                    second_val = first_val
                    first_val, first_id = a, idx
                elif a > second_val:
                    second_val = a
            total += r - first_val
            if first_id != -1:
                gain[first_id] += first_val - second_val
        return total + max(gain)

