import sys
from math import gcd

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[0], data[1]
    processes = []
    idx = 2
    for _ in range(n):
        a, p, b, q = data[idx:idx + 4]
        idx += 4
        g = gcd(a, b)
        processes.append((a, p, b, q, g))

    def minimum_cost(capacity, item):
        a, p, b, q, g = item
        best = 10**30
        # Check counts below one exchange period for either machine type.
        for s in range(b // g):
            t = max(0, (capacity - a * s + b - 1) // b)
            cost = s * p + t * q
            if cost < best:
                best = cost
        for t in range(a // g):
            s = max(0, (capacity - b * t + a - 1) // a)
            cost = s * p + t * q
            if cost < best:
                best = cost
        return best

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        total = 0
        for item in processes:
            total += minimum_cost(mid, item)
            if total > budget:
                break
        if total <= budget:
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

