from math import comb

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        m = len(s)

        # For x > 1, its reduction count is 1 + the reduction count
        # of popcount(x). The depth of 1 itself is zero.
        depth = [0] * (m + 1)
        for x in range(2, m + 1):
            depth[x] = 1 + depth[x.bit_count()]

        allowed_weights = [t for t in range(1, m + 1) if depth[t] <= k - 1]

        # For every 1-bit of n, count numbers that first differ there
        # (choosing 0), grouped by their total number of set bits.
        answer = 0
        ones_so_far = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = m - i - 1
                for weight in allowed_weights:
                    needed = weight - ones_so_far
                    if 0 <= needed <= remaining:
                        answer += comb(remaining, needed)
                ones_so_far += 1

        return answer % (10**9 + 7)

