import sys
import heapq

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    rows = data[1:]
    out = [[[] for _ in range(26)] for _ in range(n)]
    inc = [[[] for _ in range(26)] for _ in range(n)]
    dist = [[10**9] * n for _ in range(n)]
    heap = []
    missing = n * n
    max_dist = 0

    for i in range(n):
        dist[i][i] = 0
        missing -= 1
        heapq.heappush(heap, (0, i, i))
        for j, c in enumerate(rows[i]):
            if c != '-':
                k = ord(c) - 97
                out[i][k].append(j)
                inc[j][k].append(i)
                if dist[i][j] > 1:
                    dist[i][j] = 1
                    missing -= 1
                    max_dist = 1
                    heapq.heappush(heap, (1, i, j))

    while heap:
        d, x, y = heapq.heappop(heap)
        if d != dist[x][y]:
            continue
        nd = d + 2
        if missing == 0 and nd >= max_dist:
            continue
        for k in range(26):
            left = inc[x][k]
            right = out[y][k]
            if not left or not right:
                continue
            for u in left:
                row = dist[u]
                for v in right:
                    if nd < row[v]:
                        if row[v] == 10**9:
                            missing -= 1
                        row[v] = nd
                        if nd > max_dist:
                            max_dist = nd
                        heapq.heappush(heap, (nd, u, v))

    print('\n'.join(' '.join(str(-1 if value == 10**9 else value) for value in row) for row in dist))

if __name__ == '__main__':
    main()

