import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, x = data[0], data[1]
    u = data[2::2]
    d = data[3::2]

    high_bound = min(a + b for a, b in zip(u, d))

    def feasible(h):
        lo = max(0, h - d[0])
        hi = min(u[0], h)
        if lo > hi:
            return False

        for i in range(1, n):
            lo = max(max(0, h - d[i]), lo - x)
            hi = min(min(u[i], h), hi + x)
            if lo > hi:
                return False
        return True

    low = 0
    while low < high_bound:
        mid = (low + high_bound + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high_bound = mid - 1

    total = sum(a + b for a, b in zip(u, d))
    print(total - n * low)

if __name__ == '__main__':
    main()

