class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        total = n * m
        # Clockwise order in image coordinates: SE, SW, NW, NE.
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))

        def index(r, c):
            return r * m + c

        def next_index(r, c, d):
            dr, dc = dirs[d]
            r += dr
            c += dc
            if 0 <= r < n and 0 <= c < m:
                return index(r, c)
            return -1

        def scan_order(d):
            dr, dc = dirs[d]
            rows = range(n - 1, -1, -1) if dr > 0 else range(n)
            cols = range(m - 1, -1, -1) if dc > 0 else range(m)
            for r in rows:
                for c in cols:
                    yield r, c

        # straight[d][i]: longest alternating 0/2 sequence from i in d,
        # with no turn. The value at i determines the required next value.
        straight = [array('H', [0]) * total for _ in range(4)]
        for d in range(4):
            dp = straight[d]
            for r, c in scan_order(d):
                value = grid[r][c]
                if value == 1:
                    continue
                j = next_index(r, c, d)
                if j >= 0:
                    nr, nc = divmod(j, m)
                    if grid[nr][nc] != 1 and grid[nr][nc] != value:
                        dp[index(r, c)] = 1 + dp[j]
                        continue
                dp[index(r, c)] = 1

        # with_turn[d][i] allows one clockwise turn at any later point.
        # Its turned continuation is a straight sequence in the clockwise
        # direction, so all dependencies are already in straight[].
        with_turn = [array('H', [0]) * total for _ in range(4)]
        for d in range(4):
            dp = with_turn[d]
            turn_d = (d + 1) % 4
            for r, c in scan_order(d):
                value = grid[r][c]
                if value == 1:
                    continue
                best = 1
                j = next_index(r, c, d)
                if j >= 0:
                    nr, nc = divmod(j, m)
                    if grid[nr][nc] != 1 and grid[nr][nc] != value:
                        best = max(best, 1 + dp[j])
                k = next_index(r, c, turn_d)
                if k >= 0:
                    nr, nc = divmod(k, m)
                    if grid[nr][nc] != 1 and grid[nr][nc] != value:
                        best = max(best, 1 + straight[turn_d][k])
                dp[index(r, c)] = best

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                answer = max(answer, 1)
                for d in range(4):
                    j = next_index(r, c, d)
                    if j >= 0:
                        nr, nc = divmod(j, m)
                        if grid[nr][nc] == 2:
