class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # powers[i] is 10**i modulo k.
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        # The i-th digit on the left contributes to both mirrored places,
        # except for the middle digit of an odd-length palindrome.
        coef = [0] * m
        for i in range(m):
            j = n - 1 - i
            coef[i] = (powers[i] + (powers[j] if i != j else 0)) % k

        # dp[i][r]: using left-side digit positions i onward, it is
        # possible to contribute residue r modulo k.
        dp = [bytearray(k) for _ in range(m + 1)]
        dp[m][0] = 1
        for i in range(m - 1, -1, -1):
            nxt, cur, c = dp[i + 1], dp[i], coef[i]
            for r in range(k):
                for d in range(10):
                    if nxt[(r - d * c) % k]:
                        cur[r] = 1
                        break

        # Choose each left digit as large as possible while preserving
        # the possibility of completing a divisible number.
        digits = []
        need = 0
        for i, c in enumerate(coef):
            lower = 1 if i == 0 else 0
            for d in range(9, lower - 1, -1):
                rem = (need - d * c) % k
                if dp[i + 1][rem]:
                    digits.append(str(d))
                    need = rem
                    break

        left = ''.join(digits)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

