from typing import List
class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n=len(nums)
        nxt=[n]*n
        st=[]
        for i in range(n-1,-1,-1):
            while st and nums[st[-1]]<=nums[i]: st.pop()
            nxt[i]=st[-1] if st else n
            st.append(i)
        levels=n.bit_length()
        up=[nxt]
        wt=[[(nxt[i]-i)*nums[i] for i in range(n)]]
        for _ in range(1,levels):
            prev=up[-1]; pw=wt[-1]
            nu=[n]*n; nw=[0]*n
            for i in range(n):
                mid=prev[i]
                if mid<n:
                    nu[i]=prev[mid]
                    nw[i]=pw[i]+pw[mid]
            up.append(nu); wt.append(nw)
        pref=[0]*(n+1)
        for i,x in enumerate(nums): pref[i+1]=pref[i]+x
        def cost(l,r):
            pos=l; total=0
            for lev in range(levels-1,-1,-1):
                end=up[lev][pos]
                if end<=r:
                    total+=wt[lev][pos]
                    pos=end
            total+=(r+1-pos)*nums[pos]
            return total-(pref[r+1]-pref[l])
        ans=0; r=-1
        for l in range(n):
            if r<l: r=l
            while r+1<n and cost(l,r+1)<=k: r+=1
            ans+=r-l+1
        return ans

