class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        f = [0] * 26
        for ch in s:
            f[ord(ch) - 97] += 1
        n = len(s)
        ans = n
        # For each possible common positive frequency, scan the alphabet.
        # carry denotes letters moved forward from the previous position.
        for k in range(1, max(f) + 1):
            dp = {0: 0}
            for i in range(26):
                nd = {}
                for carry, cost in dp.items():
                    pool = f[i] + carry
                    # Either leave this letter absent or retain k copies.
                    for keep in (0, k):
                        # Consider no forwarding, all available surplus, and
                        # the amount useful for filling the next letter.
                        surplus = max(0, pool - keep)
                        useful = max(0, k - f[i + 1]) if i < 25 else 0
                        outs = {0, surplus, min(surplus, useful)}
                        for out in outs:
                            if out + keep > pool:
                                # Insert the missing copies.
                                local = out + keep - pool + out
                            else:
                                local = pool - out - keep + out
                            nc = cost + local
                            if i == 25 and out:
                                continue
                            nd[out] = min(nd.get(out, n + 1), nc)
                dp = nd
            ans = min(ans, min(dp.values()))
        return ans

