all_mask = (1 << n) - 1
initial_t = (1 << N) - 1
initial_a = ((1 << M) - 1) << N

@lru_cache(None)
def winning(takahashi, aoki, turn):
    hand = takahashi if turn == 0 else aoki
    if hand == 0:
        return False

    table = all_mask ^ (takahashi | aoki)
    while hand:
        card = hand & -hand
        hand -= card
        i = card.bit_length() - 1

        if turn == 0:
            next_t, next_a, next_turn = takahashi ^ card, aoki, 1
        else:
            next_t, next_a, next_turn = takahashi, aoki ^ card, 0

        # Play the card without taking anything.
        if not winning(next_t, next_a, next_turn):
            return True

        # Or take any lower-valued card that was already on the table.
        candidates = table
        while candidates:
            taken = candidates & -candidates
            candidates -= taken
            j = taken.bit_length() - 1
            if values[j] < values[i]:
                if turn == 0:
                    if not winning(next_t | taken, next_a, next_turn):
                        return True
                else:
                    if not winning(next_t, next_a | taken, next_turn):
                        return True

    return False

