from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first = p.index('*')
        second = p.index('*', first + 1)
        parts = (p[:first], p[first + 1:second], p[second + 1:])
        n = len(s)

        def occurrences(pattern):
            if not pattern:
                return list(range(n + 1))

            m = len(pattern)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = prefix[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                    prefix[i] = j

            result = []
            j = 0
            for i, char in enumerate(s):
                while j and char != pattern[j]:
                    j = prefix[j - 1]
                if char == pattern[j]:
                    j += 1
                    if j == m:
                        result.append(i - m + 1)
                        j = prefix[j - 1]
            return result

        starts, middles, ends = map(occurrences, parts)
        if not starts or not middles or not ends:
            return -1

        len_start, len_middle, len_end = map(len, parts)
        answer = n + 1
        for start in starts:
            middle_idx = bisect_left(middles, start + len_start)
            if middle_idx == len(middles):
                continue
            middle_end = middles[middle_idx] + len_middle
            end_idx = bisect_left(ends, middle_end)
            if end_idx == len(ends):
                continue
            length = ends[end_idx] + len_end - start
            answer = min(answer, length)

        return -1 if answer == n + 1 else answer

