from itertools import combinations

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    a = data[2:]

    # If K is large, enumerate the omitted elements instead.
    r = min(k, n - k)
    base = 0
    if k > n - k:
        for v in a:
            base ^= v

    ans = 0
    for subset in combinations(a, r):
        value = base
        for v in subset:
            value ^= v
        if value > ans:
            ans = value
    print(ans)

