import sys

MOD = 998244353


def ntt(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(3, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            end = start + half
            for j in range(start, end):
                u = a[j]
                v = a[j + half] * w % MOD
                x = u + v
                if x >= MOD:
                    x -= MOD
                y = u - v
                if y < 0:
                    y += MOD
                a[j] = x
                a[j + half] = y
                w = w * wlen % MOD
        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    count = data[0]
    values = data[1:]

    # For small sets, direct enumeration avoids transform overhead.
    if count < 3000:
        present = set(values)
        answer = 0
        for b in values:
            for a in values:
                if a < b and 2 * b - a in present:
                    answer += 1
        print(answer)
        return

    maximum = max(values)
    size = 1
    while size < 2 * maximum + 1:
        size <<= 1

    polynomial = [0] * size
    for value in values:
        polynomial[value] = 1

    ntt(polynomial, False)
    for i, coefficient in enumerate(polynomial):
        polynomial[i] = coefficient * coefficient % MOD
    ntt(polynomial, True)

    # The coefficient for 2*b counts ordered pairs summing to 2*b.
    # Remove (b,b), then divide by two for the two orders of each pair.
    print(sum((polynomial[2 * b] - 1) // 2 for b in values))


