class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        mins = [None] * k
        mins[0] = 0
        pref = 0
        ans = -10**30
        for i, x in enumerate(nums, 1):
            pref += x
            r = i % k
            m = mins[r]
            if m is not None:
                ans = max(ans, pref - m)
            if m is None or pref < m:
                mins[r] = pref
        return ans

