    sieve[0] = 0
if M >= 1:
    sieve[1] = 0

for p in range(2, math.isqrt(M) + 1):
    if sieve[p]:
        start = p * p
        sieve[start:M + 1:p] = b'\x00' * (((M - start) // p) + 1)

primes = [p for p in range(2, M + 1) if sieve[p]]
answer = 0

# Count p^2 q^2, where p and q are distinct primes and p < q.
for i, p in enumerate(primes):
    if p * p > M:
        break
    answer += bisect.bisect_right(primes, M // p) - i - 1

# Count p^8.
for p in primes:
    if p ** 8 <= N:
        answer += 1
    else:
        break

