class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        lengths = [1] * 26

        # lengths[i] is the expansion length of character i after
        # the number of transformations processed so far.
        for _ in range(t):
            nxt = [0] * 26
            for i in range(25):
                nxt[i] = lengths[i + 1]
            nxt[25] = (lengths[0] + lengths[1]) % MOD
            lengths = nxt

        return sum(lengths[ord(ch) - ord('a')] for ch in s) % MOD

