class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 1:
            return 0

        # Find the nearest index to the right with a strictly larger value.
        next_greater = [n - 1] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                next_greater[i] = stack[-1]
            stack.append(i)

        score = 0
        i = 0
        while i < n - 1:
            j = next_greater[i]
            score += (j - i) * nums[i]
            i = j
        return score

