import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10000
        prime = bytearray(b'\x01') * limit
        prime[0:2] = b'\x00\x00'
        for p in range(2, 100):
            if prime[p]:
                start = p * p
                prime[start:limit:p] = b'\x00' * (((limit - 1 - start) // p) + 1)

        if prime[n] or prime[m]:
            return -1

        dist = {n: n}
        pq = [(n, n)]
        while pq:
            cost, x = heapq.heappop(pq)
            if cost != dist.get(x):
                continue
            if x == m:
                return cost

            digits = list(str(x))
            for i, ch in enumerate(digits):
                d = ord(ch) - 48
                for nd in (d - 1, d + 1):
                    if not 0 <= nd <= 9:
                        continue
                    new_digits = digits.copy()
                    new_digits[i] = chr(48 + nd)
                    y = int(''.join(new_digits))
                    if prime[y]:
                        continue
                    new_cost = cost + y
                    if new_cost < dist.get(y, float('inf')):
                        dist[y] = new_cost
                        heapq.heappush(pq, (new_cost, y))
        return -1

