from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        def z_counts(a, threshold=0):
            m = len(a)
            z = [0] * m
            left = right = 0
            total = tail = 0

            for k in range(1, m):
                if k <= right:
                    z[k] = min(right - k + 1, z[k - left])

                while k + z[k] < m and a[z[k]] == a[k + z[k]]:
                    z[k] += 1

                if z[k] >= k:
                    total += 1
                    if k >= threshold:
                        tail += 1

                end = k + z[k] - 1
                if end > right:
                    left, right = k, end

            return total, tail, z

        _, _, whole_z = z_counts(nums)
        answer = 0

        for i in range(1, n - 1):
            m = n - i
            second_count, overlap_count, _ = z_counts(nums[i:], i)

            # nums2 is a prefix of nums3.
            answer += second_count

            # nums1 is a prefix of nums2; add the splits not already counted.
            if whole_z[i] >= i:
                answer += max(0, m - i) - overlap_count

        return answer

