from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        targets = set(targetIndices)
        m = len(pattern)
        inf = len(targetIndices) + 1
        dp = [inf] * (m + 1)
        dp[0] = 0

        for i, char in enumerate(source):
            cost = int(i in targets)
            # Descending order ensures this source character is used at most once.
            for j in range(m - 1, -1, -1):
                if char == pattern[j] and dp[j] < inf:
                    dp[j + 1] = min(dp[j + 1], dp[j] + cost)

        # Every target index not needed by the chosen pattern embedding can be removed.
        return len(targetIndices) - dp[m]

