import heapq
class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        rev = [[] for _ in range(n)]
        for a,b,w in edges:
            rev[b].append((a,w))
        inf = 10**18
        dist = [inf]*n
        dist[0]=0
        pq=[(0,0)]
        while pq:
            d,v=heapq.heappop(pq)
            if d != dist[v]:
                continue
            for u,w in rev[v]:
                nd=max(d,w)
                if nd < dist[u]:
                    dist[u]=nd
                    heapq.heappush(pq,(nd,u))
        ans=max(dist)
        return -1 if ans==inf else ans

