class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # A state assigns colors to one mirrored pair: (left, right).
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        # Moving inward, both corresponding sides must differ from
        # the previous pair to satisfy adjacency constraints.
        for i in range(1, n // 2):
            ndp = [float('inf')] * len(states)
            for j, (a, b) in enumerate(states):
                pair_cost = cost[i][a] + cost[n - 1 - i][b]
                for k, (prev_a, prev_b) in enumerate(states):
                    if a != prev_a and b != prev_b:
                        ndp[j] = min(ndp[j], dp[k] + pair_cost)
            dp = ndp

        return min(dp)

